#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <fribidi.h>

int LLVMFuzzerTestOneInput (const uint8_t *data, size_t size)
{
  const FriBidiStrIndex str_len = size / 4;
  FriBidiChar *str = (FriBidiChar *) data;
  FriBidiCharType *types = calloc (str_len, sizeof (FriBidiCharType));
  FriBidiBracketType *btypes = calloc (str_len, sizeof (FriBidiBracketType));
  FriBidiLevel *levels = calloc (str_len, sizeof (FriBidiLevel));
  fribidi_get_bidi_types (str, str_len, types);
  fribidi_get_bracket_types (str, str_len, types, btypes);
  FriBidiParType par_type = FRIBIDI_PAR_ON;
  FriBidiLevel level = fribidi_get_par_embedding_levels_ex (types, btypes, str_len, &par_type, levels);
  free (types);
  free (btypes);
  free (levels);
  return 0;
}

// xorshift RNG
static uint32_t rng_state = 12345;
static uint32_t rng(void) {
  rng_state ^= rng_state << 13;
  rng_state ^= rng_state >> 17;
  rng_state ^= rng_state << 5;
  return rng_state;
}

int main(void) {
  // alphabet of interesting chars
  uint32_t alpha[] = {
    0x2066, 0x2067, 0x2068, 0x2069, // LRI RLI FSI PDI
    0x202A, 0x202B, 0x202D, 0x202E, 0x202C, // LRE RLE LRO RLO PDF
    0x0041, 0x05D0, 0x0627, 0x0030, 0x0020, // L R AL EN WS
    0x00AD, 0x200B, 0x2028, 0x000A, 0x0028, 0x0029, // NSM ZWSP LS BS ( )
    0x002B, 0x002C, 0x002E, 0x003A, 0x0023, // ES CS ET
  };
  int nalpha = sizeof(alpha)/sizeof(alpha[0]);
  for (long iter = 0; iter < 2000000; iter++) {
    int len = 1 + (rng() % 300);
    uint32_t buf[300];
    for (int i = 0; i < len; i++) {
      buf[i] = alpha[rng() % nalpha];
    }
    LLVMFuzzerTestOneInput((uint8_t*)buf, len*4);
  }
  printf("done no crash\n");
  return 0;
}
EOF
cd /tmp && gcc -fsanitize=address -g -O1 -I/workspace/repo-vul/src-vul/fribidi/lib -I/tmp/build/lib -I/tmp/build/gen.tab fuzz.c /tmp/build/lib/libfribidi.a -o fuzz 2>&1 | tail -5 && echo "BUILD OK"

